package com.mamtrex.hospital.inventory;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="inventory_items") public class InventoryItem extends BaseEntity { private String sku; private String name; private String category; private String quantity; private String reorderLevel; protected InventoryItem(){} public InventoryItem(String sku, String name, String category, String quantity, String reorderLevel){this.sku=sku; this.name=name; this.category=category; this.quantity=quantity; this.reorderLevel=reorderLevel;} public String getSku(){return sku;} public String getName(){return name;} public String getCategory(){return category;} public String getQuantity(){return quantity;} public String getReorderLevel(){return reorderLevel;} }
